-- B1: module-owned schemas. Cross-module IDs are validated through public APIs.
CREATE SCHEMA m00; CREATE SCHEMA m01; CREATE SCHEMA m02; CREATE SCHEMA m03; CREATE SCHEMA m04;
CREATE SCHEMA ops;
CREATE TABLE m00.app_user(
 id text PRIMARY KEY, login_name varchar(128) NOT NULL UNIQUE, display_name varchar(128) NOT NULL,
 password_hash text NOT NULL, status text NOT NULL CHECK(status IN('ACTIVE','DISABLED')),
 created_at timestamptz(6) NOT NULL DEFAULT now(), updated_at timestamptz(6) NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 1);
CREATE TABLE m00.app_role(code text PRIMARY KEY, name text NOT NULL, permission_codes text[] NOT NULL);
CREATE TABLE m00.user_role(user_id text REFERENCES m00.app_user(id), role_code text REFERENCES m00.app_role(code),factory_id text NOT NULL,PRIMARY KEY(user_id,role_code,factory_id));
CREATE TABLE m00.user_session(token_hash char(64) PRIMARY KEY,user_id text NOT NULL REFERENCES m00.app_user(id),csrf_hash char(64) NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),expires_at timestamptz(6) NOT NULL,revoked_at timestamptz(6));
CREATE INDEX user_session_expiry ON m00.user_session(expires_at);
CREATE TABLE m00.access_credential(id text PRIMARY KEY,token_hash char(64) NOT NULL UNIQUE,factory_id text NOT NULL,device_ids text[] NOT NULL CHECK(cardinality(device_ids)>0),data_environment text NOT NULL CHECK(data_environment IN('SIMULATED','REAL')),scopes text[] NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),expires_at timestamptz(6) NOT NULL,revoked_at timestamptz(6),version bigint NOT NULL DEFAULT 1);
CREATE TABLE m00.audit_event(id uuid PRIMARY KEY,factory_id text,actor_type text NOT NULL CHECK(actor_type IN('USER','DEVICE','SYSTEM','ANONYMOUS')),actor_id text,action text NOT NULL,resource_type text NOT NULL,resource_id text,request_id text NOT NULL,occurred_at timestamptz(6) NOT NULL DEFAULT now(),result text NOT NULL CHECK(result IN('SUCCESS','FAILURE')),details jsonb NOT NULL DEFAULT '{}');
CREATE INDEX audit_scope_time ON m00.audit_event(factory_id,occurred_at DESC,id);
CREATE INDEX audit_request ON m00.audit_event(request_id);
CREATE TABLE m01.factory(id text PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,timezone text NOT NULL,status text NOT NULL CHECK(status IN('ACTIVE','DISABLED')),created_at timestamptz(6) NOT NULL DEFAULT now());
CREATE TABLE m01.production_line(id text PRIMARY KEY,factory_id text NOT NULL REFERENCES m01.factory(id),code text NOT NULL,name text NOT NULL,UNIQUE(factory_id,code));
CREATE TABLE m01.inspection_process(id text PRIMARY KEY,factory_id text NOT NULL REFERENCES m01.factory(id),code text NOT NULL,name text NOT NULL,UNIQUE(factory_id,code));
CREATE TABLE m01.device(id text PRIMARY KEY,factory_id text NOT NULL REFERENCES m01.factory(id),line_id text NOT NULL REFERENCES m01.production_line(id),process_id text NOT NULL REFERENCES m01.inspection_process(id),code text NOT NULL,name text NOT NULL,metric_code text NOT NULL CHECK(metric_code IN('SHIELD_OVERLAP_RATE','WIRE_GAP','OVALITY')),model text NOT NULL,enabled boolean NOT NULL DEFAULT false,data_environment text NOT NULL CHECK(data_environment IN('SIMULATED','REAL')),capability_version text NOT NULL,raw_schema_versions text[] NOT NULL,source_identification text NOT NULL,source_metadata jsonb NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(factory_id,code));
CREATE TABLE m01.product_specification(id text PRIMARY KEY,factory_id text NOT NULL REFERENCES m01.factory(id),code text NOT NULL,name text NOT NULL,voltage_kv numeric(10,3) NOT NULL CHECK(voltage_kv BETWEEN 35 AND 220),conductor_area_mm2 numeric(16,4) NOT NULL CHECK(conductor_area_mm2>0),core_count integer NOT NULL CHECK(core_count>0),shield_structure text NOT NULL,enabled boolean NOT NULL DEFAULT true,source_metadata jsonb NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(factory_id,code));
CREATE TABLE m01.specification_applicability(specification_id text REFERENCES m01.product_specification(id),process_id text REFERENCES m01.inspection_process(id),metric_code text NOT NULL,PRIMARY KEY(specification_id,process_id,metric_code));
CREATE TABLE m03.metric_definition(code text PRIMARY KEY,name text NOT NULL,unit text NOT NULL,display_scale integer NOT NULL CHECK(display_scale BETWEEN 0 AND 10));
CREATE TABLE m03.recipe_version(id text PRIMARY KEY,factory_id text NOT NULL,metric_code text NOT NULL REFERENCES m03.metric_definition(code),revision text NOT NULL,approval_state text NOT NULL CHECK(approval_state IN('UNAPPROVED','TEST_ONLY','APPROVED')),rule_snapshot jsonb NOT NULL,source_metadata jsonb NOT NULL,snapshot_hash char(64) NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now());
CREATE TABLE m02.work_order(id text PRIMARY KEY,factory_id text NOT NULL,source_system text NOT NULL,external_code varchar(128) NOT NULL,specification_id text NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),UNIQUE(factory_id,source_system,external_code));
CREATE TABLE m02.cable_spool(id text PRIMARY KEY,factory_id text NOT NULL,work_order_id text NOT NULL REFERENCES m02.work_order(id),spool_code varchar(128) NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),UNIQUE(factory_id,work_order_id,spool_code));
CREATE TABLE m02.inspection_task(id text PRIMARY KEY,factory_id text NOT NULL,task_code text NOT NULL,work_order_id text NOT NULL REFERENCES m02.work_order(id),spool_id text NOT NULL REFERENCES m02.cable_spool(id),device_id text NOT NULL,process_id text NOT NULL,specification_id text NOT NULL,metric_code text NOT NULL,recipe_version_id text,planned_length_m numeric(24,10) NOT NULL CHECK(planned_length_m>0),data_environment text NOT NULL CHECK(data_environment IN('SIMULATED','REAL')),state text NOT NULL CHECK(state IN('CREATED','RUNNING','ENDED')),version bigint NOT NULL DEFAULT 1,rule_snapshot jsonb NOT NULL,context_snapshot jsonb NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),started_at timestamptz(6),ended_at timestamptz(6),end_reason text,UNIQUE(factory_id,task_code));
CREATE UNIQUE INDEX one_running_task ON m02.inspection_task(device_id) WHERE state='RUNNING';
CREATE INDEX task_spool ON m02.inspection_task(factory_id,spool_id,created_at DESC,id);
CREATE TABLE m02.command_receipt(factory_id text NOT NULL,actor_id text NOT NULL,command_key text NOT NULL,payload_hash char(64) NOT NULL,response jsonb NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),PRIMARY KEY(factory_id,actor_id,command_key));
CREATE TABLE m02.task_transition(id uuid PRIMARY KEY,task_id text NOT NULL REFERENCES m02.inspection_task(id),from_state text,to_state text NOT NULL,actor_id text NOT NULL,request_id text NOT NULL,reason text,task_version bigint NOT NULL,occurred_at timestamptz(6) NOT NULL DEFAULT now());
CREATE TABLE m02.task_device_binding(id text PRIMARY KEY,task_id text NOT NULL REFERENCES m02.inspection_task(id),device_id text NOT NULL,factory_id text NOT NULL,binding_version numeric(20,0) NOT NULL,assignment jsonb NOT NULL,snapshot_hash char(64) NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),UNIQUE(device_id,binding_version));
CREATE TABLE m02.binding_ack(id text PRIMARY KEY,factory_id text NOT NULL,device_id text NOT NULL,binding_id text NOT NULL REFERENCES m02.task_device_binding(id),payload_hash char(64) NOT NULL,payload jsonb NOT NULL,result text NOT NULL CHECK(result IN('APPLIED','REJECTED')),capture_session_id text,first_capture_sequence numeric(20,0),effective_at timestamptz(6),recorded_at timestamptz(6) NOT NULL DEFAULT now(),UNIQUE(device_id,id));
CREATE INDEX binding_capture ON m02.binding_ack(device_id,capture_session_id,first_capture_sequence DESC) WHERE result='APPLIED';
CREATE TABLE m04.device_connection(id text PRIMARY KEY,factory_id text NOT NULL,device_id text NOT NULL,client_session_id text NOT NULL,payload_hash char(64) NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now(),superseded_at timestamptz(6),last_heartbeat_sequence numeric(20,0),last_heartbeat_at timestamptz(6),online_until timestamptz(6),heartbeat_payload jsonb,UNIQUE(device_id,client_session_id));
CREATE UNIQUE INDEX one_live_connection ON m04.device_connection(device_id) WHERE superseded_at IS NULL;
CREATE TABLE m04.ingestion_batch(id uuid PRIMARY KEY,request_id text NOT NULL,source_batch_id text NOT NULL,factory_id text NOT NULL,credential_id text NOT NULL,received_at timestamptz(6) NOT NULL DEFAULT now(),completed_at timestamptz(6),total integer NOT NULL,stored integer NOT NULL DEFAULT 0,duplicate integer NOT NULL DEFAULT 0,quarantined integer NOT NULL DEFAULT 0,rejected integer NOT NULL DEFAULT 0,state text NOT NULL CHECK(state IN('PROCESSING','COMPLETED')),CHECK(total>0 AND total<=500));
CREATE INDEX ingestion_batch_request ON m04.ingestion_batch(request_id);
CREATE TABLE m04.measurement_record(id text PRIMARY KEY,ingest_order bigint GENERATED ALWAYS AS IDENTITY UNIQUE,factory_id text NOT NULL,device_id text NOT NULL,source_record_key text NOT NULL,capture_session_id text NOT NULL,capture_sequence numeric(20,0) NOT NULL CHECK(capture_sequence BETWEEN 0 AND 18446744073709551615),source_record_id text,source_session_id text,source_sequence text,task_id text,binding_id text,binding_version numeric(20,0),recipe_version_id text,sample_kind text NOT NULL CHECK(sample_kind IN('NEW_SAMPLE','READ_SNAPSHOT')),sample_time timestamptz(6) NOT NULL,received_at timestamptz(6) NOT NULL DEFAULT now(),time_source text NOT NULL,position_m numeric(24,10),position_quality text NOT NULL,position_segment_id text,position_eligibility text NOT NULL DEFAULT 'UNVERIFIED' CHECK(position_eligibility='UNVERIFIED'),source_type text NOT NULL,data_environment text NOT NULL CHECK(data_environment IN('SIMULATED','REAL')),data_status text NOT NULL CHECK(data_status IN('VALID','INVALID','MISSING')),receipt_status text NOT NULL CHECK(receipt_status IN('STORED','QUARANTINED')),isolation_reason text,raw_payload jsonb NOT NULL,payload_hash char(64) NOT NULL,canonical_version text NOT NULL DEFAULT 'ingest-c14n.v1',schema_version text NOT NULL CHECK(schema_version='1.0'),UNIQUE(factory_id,device_id,source_record_key),UNIQUE(factory_id,device_id,capture_session_id,capture_sequence));
CREATE INDEX measurement_task_time ON m04.measurement_record(factory_id,task_id,sample_time DESC,id);
CREATE INDEX measurement_device_ingest ON m04.measurement_record(factory_id,device_id,ingest_order);
CREATE INDEX measurement_quarantine ON m04.measurement_record(factory_id,received_at,id) WHERE receipt_status='QUARANTINED';
CREATE TABLE m04.measurement_value(record_id text PRIMARY KEY REFERENCES m04.measurement_record(id),metric_code text NOT NULL CHECK(metric_code IN('SHIELD_OVERLAP_RATE','WIRE_GAP','OVALITY')),value numeric(24,10),unit text NOT NULL,data_status text NOT NULL CHECK(data_status IN('VALID','INVALID','MISSING')),source_quality_result text NOT NULL CHECK(source_quality_result IN('PASS','FAIL','NOT_EVALUATED')),method_id text,window_definition jsonb NOT NULL,reason_code text,CHECK((data_status='VALID' AND value IS NOT NULL)OR(data_status<>'VALID' AND value IS NULL)));
CREATE TABLE m04.measurement_evaluation(record_id text REFERENCES m04.measurement_record(id),version bigint NOT NULL,quality_result text NOT NULL CHECK(quality_result IN('PASS','FAIL','NOT_EVALUATED')),reason_code text,recipe_version_id text,rule_snapshot jsonb NOT NULL,evaluated_at timestamptz(6) NOT NULL DEFAULT now(),PRIMARY KEY(record_id,version));
CREATE TABLE m04.measurement_qualification(record_id text REFERENCES m04.measurement_record(id),version bigint NOT NULL,eligibility text NOT NULL CHECK(eligibility IN('EFFECTIVE','QUARANTINED')),reason_code text,created_at timestamptz(6) NOT NULL DEFAULT now(),PRIMARY KEY(record_id,version));
CREATE TABLE m04.ingestion_item(batch_id uuid REFERENCES m04.ingestion_batch(id),input_index integer NOT NULL,source_id text,stored_id text REFERENCES m04.measurement_record(id),receipt_status text NOT NULL,error_code text,field_errors jsonb NOT NULL DEFAULT '[]',payload_hash char(64),created_at timestamptz(6) NOT NULL DEFAULT now(),PRIMARY KEY(batch_id,input_index));
CREATE INDEX ingestion_item_errors ON m04.ingestion_item(error_code,created_at DESC) WHERE error_code IS NOT NULL;
CREATE TABLE m04.ingestion_conflict(id uuid PRIMARY KEY,factory_id text NOT NULL,device_id text NOT NULL,source_id text NOT NULL,original_record_id text NOT NULL REFERENCES m04.measurement_record(id),conflicting_hash char(64) NOT NULL,request_id text NOT NULL,reason_code text NOT NULL,created_at timestamptz(6) NOT NULL DEFAULT now());
CREATE TABLE m04.measurement_outbox(event_id uuid PRIMARY KEY,event_type text NOT NULL,schema_version text NOT NULL,factory_id text NOT NULL,data_environment text NOT NULL,aggregate_id text NOT NULL REFERENCES m04.measurement_record(id),aggregate_version bigint NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz(6) NOT NULL DEFAULT now(),UNIQUE(event_type,aggregate_id,aggregate_version));
CREATE INDEX outbox_order ON m04.measurement_outbox(occurred_at,event_id);
CREATE TABLE ops.process_heartbeat(process_name text PRIMARY KEY,instance_id uuid NOT NULL,pid integer NOT NULL,capabilities text[] NOT NULL,last_seen_at timestamptz(6) NOT NULL DEFAULT now());
-- Append-only facts cannot be overwritten even by the ordinary runtime role.
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA m00,m01,m02,m03,m04,ops TO hy_runtime;
GRANT SELECT,INSERT,UPDATE ON ALL TABLES IN SCHEMA m00,m01,m02,m03,m04,ops TO hy_runtime;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA m00,m01,m02,m03,m04,ops TO hy_runtime;
REVOKE UPDATE ON m00.audit_event,m03.recipe_version,m02.task_transition,m02.task_device_binding,m02.binding_ack,m02.command_receipt,m04.measurement_record,m04.measurement_value,m04.measurement_evaluation,m04.measurement_qualification,m04.ingestion_item,m04.ingestion_conflict,m04.measurement_outbox FROM hy_runtime;
